  "headword": { "ru": "говори́ть", "plain": "говорить" },
  "overview": {
    "gloss": "to speak, to talk, to say",
    "facts": [
      { "label": "Aspect", "value": "imperfective" },
      { "label": "Aspect partner", "value": "поговори́ть (pf, to have a talk) / сказа́ть (pf, to say)" },
      { "label": "Conjugation class", "value": "II" },
      { "label": "Stress pattern", "value": "fixed on the ending in most forms; shifts to stem in some imperative/short forms — see tables" },
      { "label": "Transitivity", "value": "transitive/intransitive (both: говори́ть что / говори́ть с кем)" },
      { "label": "Register", "value": "neutral, extremely common" },
      { "label": "Frequency", "value": "one of the most frequent Russian verbs" }
    ],
    "notes": [
      "Perfective сказа́ть covers single completed utterances; поговори́ть covers a bounded conversation.",
      "No unrelated homograph exists for this word."
    ]
  },
  "sections": [
    {
      "id": "verb-nonpast",
      "layout": "grid",
      "title": { "en": "Present & future", "ru": "Настоящее и будущее" },
