        "rowLabels": ["я", "ты", "он / она / оно", "мы", "вы", "они"],
        "colLabels": ["Present", "Future"],
        "cells": [
          [ { "ru": "говорю́", "plain": "говорю" }, { "ru": "бу́ду говори́ть", "plain": "буду говорить" } ],
