          [ { "ru": "говори́ли", "plain": "говорили" }, { "ru": "говори́ли бы", "plain": "говорили бы" } ]
        ]
      }
    },
    {
      "id": "verb-imperative",
      "layout": "grid",
      "title": { "en": "Imperative", "ru": "Повелительное" },
      "grid": {
        "rowLabels": ["ты", "вы"],
        "colLabels": ["Imperative"],
        "cells": [
          [ { "ru": "говори́", "plain": "говори" } ],
          [ { "ru": "говори́те", "plain": "говорите" } ]
        ]
      },
      "note": "Negated commands typically use the imperfective («Не говори́ никому́» — don't tell anyone), while affirmative single-action commands often prefer the perfective сказа́ть/скажи́."
    },
    {
      "id": "verb-participles",
      "layout": "grid",
      "title": { "en": "Participles", "ru": "Причастия" },
      "grid": {
        "rowLabels": ["Present active", "Past active", "Present passive", "Past passive", "Past passive short (m / f / n / pl)"],
