          [ { "ru": "говори́мый", "plain": "говоримый", "gloss": "being said/spoken (rare, bookish)" } ],
          [ null ],
          [ null ]
        ]
      },
      "note": "No past passive participle exists for говори́ть (imperfective process verbs of speech rarely form one); use сказа́ть's ска́занный instead for completed statements."
