    {
      "id": "verb-gerunds",
      "layout": "list",
      "title": { "en": "Verbal adverbs", "ru": "Деепричастия" },
      "rows": [
        { "ru": "говоря́", "plain": "говоря", "gloss": "while speaking/saying", "example": { "ru": "Говоря́ откры́то, я не согла́сен.", "en": "Speaking frankly, I disagree." } }
      ],
      "note": "No past gerund is normally used for this imperfective verb; the compound form говори́вши is archaic/unused."
    },
    {
      "id": "verb-family",
      "layout": "list",
      "title": { "en": "Aspect pair & word family", "ru": "Видовая пара и семья слова" },
      "rows": [
        { "ru": "поговори́ть", "plain": "поговорить", "gloss": "to have a talk (completed)", "tags": ["partner", "pf"], "example": { "ru": "Нам на́до поговори́ть.", "en": "We need to talk." } },
        { "ru": "сказа́ть", "plain": "сказать", "gloss": "to say/tell (single completed utterance)", "tags": ["partner", "pf"], "example": { "ru": "Скажи́ мне пра́вду.", "en": "Tell me the truth." } },
        { "ru": "разговори́ться", "plain": "разговориться", "gloss": "to get talking, warm up to conversation", "tags": ["pf", "refl"], "example": { "ru": "Мы разговори́лись и не заме́тили вре́мя.", "en": "We got talking and lost track of time." } },
        { "ru": "догова́риваться", "plain": "договариваться", "gloss": "to negotiate, come to an agreement (process)", "tags": ["impf", "prefix:до-", "refl"], "example": { "ru": "Они догова́риваются о встре́че.", "en": "They're arranging a meeting." } },
        { "ru": "договори́ться", "plain": "договориться", "gloss": "to reach an agreement (completed)", "tags": ["pf", "prefix:до-", "refl"], "example": { "ru": "Мы договори́лись встре́титься в пять.", "en": "We agreed to meet at five." } },
        { "ru": "проговори́ться", "plain": "проговориться", "gloss": "to let slip, blurt out a secret", "tags": ["pf", "prefix:про-", "refl"], "example": { "ru": "Он проговори́лся о сюрпри́зе.", "en": "He let slip about the surprise." } },
        { "ru": "отговори́ть", "plain": "отговорить", "gloss": "to talk someone out of something", "tags": ["pf", "prefix:от-"], "example": { "ru": "Я отговори́л его́ от пое́здки.", "en": "I talked him out of the trip." } },
        { "ru": "угова́ривать", "plain": "уговаривать", "gloss": "to persuade, talk into (process)", "tags": ["impf", "prefix:у-"], "example": { "ru": "Не угова́ривай меня́.", "en": "Don't try to talk me into it." } },
        { "ru": "разговор", "plain": "разговор", "gloss": "a conversation, talk", "tags": ["noun"], "example": { "ru": "У нас был серьёзный разгово́р.", "en": "We had a serious conversation." } },
        { "ru": "говор", "plain": "говор", "gloss": "a dialect, accent; murmur of speech", "tags": ["noun"], "example": { "ru": "У него́ ю́жный го́вор.", "en": "He has a southern accent." } },
        { "ru": "говорли́вый", "plain": "говорливый", "gloss": "talkative, chatty", "tags": ["adj"], "example": { "ru": "Она́ о́чень говорли́вая.", "en": "She's very talkative." } }
      ]
    },
    {
      "id": "verb-government",
      "layout": "list",
      "title": { "en": "Government & collocations", "ru": "Управление и сочетаемость" },
      "rows": [
        { "ru": "говори́ть с кем-либо", "plain": "говорить с кем-либо", "gloss": "to talk with someone — с + instr.", "example": { "ru": "Я говорю́ с сестро́й по телефо́ну.", "en": "I'm talking with my sister on the phone." } },
        { "ru": "говори́ть о чём-либо / о ком-либо", "plain": "говорить о чём-либо / о ком-либо", "gloss": "to talk about something/someone — о + prep.", "example": { "ru": "Мы говори́ли о фи́льме.", "en": "We talked about the film." } },
        { "ru": "говори́ть на языке́", "plain": "говорить на языке", "gloss": "to speak a language — на + prep.", "example": { "ru": "Она́ говори́т на трёх языка́х.", "en": "She speaks three languages." } },
        { "ru": "говори́ть, что…", "plain": "говорить, что…", "gloss": "to say that… (introduces reported speech)", "example": { "ru": "Он говори́т, что придёт по́зже.", "en": "He says he'll come later." } },
        { "ru": "говоря́т, что…", "plain": "говорят, что…", "gloss": "they say that… (hearsay, impersonal)", "example": { "ru": "Говоря́т, что бу́дет дождь.", "en": "They say it's going to rain." } },
        { "ru": "по пра́вде говоря́", "plain": "по правде говоря", "gloss": "to tell the truth (fixed phrase)", "example": { "ru": "По пра́вде говоря́, мне всё равно́.", "en": "To tell the truth, I don't care." } }
      ]
    }
  ]
